    "key_characteristics": [
      {
        "attribute": "Same Value, Different Form",
        "explanation": "Equivalent fractions express identical numerical values using different numerator and denominator pairs, such as 3/6 and 1/2."
      },
      {
        "attribute": "Multiplicative Relationship",
        "explanation": "Fractions are equivalent when one can be obtained by multiplying or dividing both the numerator and denominator of another by the same non-zero number."
      }
    ],
    "applications_use_cases": [
      {
        "application": "Mathematics Education (K–8 Curriculum)",
        "example": "Teachers use equivalent fractions to help students understand fraction equivalence before introducing operations like addition and subtraction with unlike denominators."
      },
      {
        "application": "Real-World Measurement & Proportions",
