  "analyses": {
    "Definition & Scope": {
      "definition": "The Pythagorean Theorem states that in a right triangle, the square of the hypotenuse equals the sum of the squares of the other two sides (a² + b² = c²). Its converse states that if a² + b² = c², then the triangle is a right triangle.",
      "boundaries": "Differs from general triangle laws (e.g., Law of Cosines) by applying only to right triangles; the converse establishes a condition for right angles, not just a property of them."
    },
    "Key Characteristics": [
      {
        "attribute": "Geometric Foundation",
        "explanation": "Relies on the properties of right triangles and the relationship between side lengths, forming a cornerstone of Euclidean geometry."
      },
      {
        "attribute": "Bidirectional Logic",
        "explanation": "The theorem and its converse provide both a necessary and sufficient condition for right angles in triangles."
      }
    ],
    "Applications & Use Cases": [
      {
        "application": "Architecture and Construction",
        "example": "Used to ensure corners are square; for example, builders use the 3-4-5 triangle rule (3² + 4² = 5²) to verify right angles in foundations."
      },
      {
        "application": "Navigation and GPS Systems",
        "example": "Calculates shortest distance between two points on a plane, such as determining straight-line distance between two GPS coordinates using the theorem."
      }
    ]
  }
}

